type User = { id: number; name: string; email: string; created_at?: string }
type Dataset = { id?: number; name: string; rows: number; columns: number; quality: number; lastUpdated: string; missing?: number; duplicates?: number; column_names?: string[] }
type DatasetRecord = { id: number; name: string; rows: number; columns: number; quality_score: number; missing_values: number; duplicates: number; file_size: number; column_names: string[]; columns_detail: { name: string; dtype: string; missing: number; unique: number }[]; numeric_columns: string[]; categorical_columns: string[]; date_columns?: string[]; date_range?: { column: string; start: string; end: string } | null; status: string; created_at?: string }
type Insight = { category: string; title: string; detail: string; metric: string; tone: string; link: string }
type QueryResult = { answer: string; agents?: string[]; breakdown?: Record<string, number>; simulation?: { current: number; simulated: number; change_percent: number }; chart?: DashboardResponse['chart']; supporting_data?: unknown[]; intent?: string }
type DashboardResponse = { dataset: DatasetRecord; profile: Record<string, unknown>; kpis: { label: string; value: number; detail?: string }[]; chart?: { type: string; title: string; x?: string; y?: string; data?: { label: string; value: number }[] } | null }
// NO_DATA -> UPLOAD_SELECTED -> UPLOADING -> PROCESSING -> READY, with PROCESSING/UPLOADING -> ERROR -> retry.
type DatasetStatus = 'NO_DATA' | 'UPLOAD_SELECTED' | 'UPLOADING' | 'PROCESSING' | 'READY' | 'ERROR'

const API = 'http://127.0.0.1:8000'
const ACCEPTED_EXTENSIONS = ['.csv', '.xlsx', '.xls']
const MAX_UPLOAD_BYTES = 25 * 1024 * 1024
const navItems = [
  ['Dashboard', '/dashboard', '◈'], ['Datasets', '/datasets', '▦'], ['Ask Data', '/ask-data', '✣'], ['Insights', '/insights', '◒'], ['Predictions', '/predictions', '⌁'], ['Anomalies', '/anomalies', '△'], ['Recommendations', '/recommendations', '✦'], ['What-If', '/what-if', '↗'], ['Reports', '/reports', '▤'],
]

// Each tab keeps the token it signed in with. localStorage is shared by every tab of the browser, so reading
// it per request would let a sign-in in another tab silently switch this tab to a different account mid-session.
let tabToken: string | null = localStorage.getItem('datanova_token')
const sessionToken = () => tabToken
function clearSession() { tabToken = null; sessionStorage.removeItem('datanova_account_switched'); ['datanova_token', 'datanova_user', 'datanova_dataset', 'datanova_last_query'].forEach((key) => localStorage.removeItem(key)) }
async function api<T>(path: string, options?: RequestInit): Promise<T> {
  const headers = new Headers(options?.headers)
  const token = sessionToken()
  if (token) headers.set('Authorization', `Bearer ${token}`)
  let response: Response
  try { response = await fetch(`${API}${path}`, { ...options, headers }) } catch { throw new Error(`Could not reach the DataNova API at ${API}. Check that the backend is running.`) }
  const body = await response.json().catch(() => ({}))
  if (response.status === 401 && token && !path.startsWith('/api/auth/')) { clearSession(); window.location.assign('/login') }
  if (!response.ok) throw new Error(body.detail || 'Something went wrong. Please try again.')
  return body as T
}
const postQuery = (question: string, datasetId: number) => api<QueryResult>('/api/query', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ question, dataset_id: datasetId }) })

type ThemePreference = 'light' | 'system' | 'dark'
const THEME_KEY = 'datanova_theme'
const darkQuery = window.matchMedia('(prefers-color-scheme: dark)')
function readThemePreference(): ThemePreference { const value = localStorage.getItem(THEME_KEY); return value === 'dark' || value === 'system' ? value : 'light' }
function applyTheme(preference: ThemePreference) { document.documentElement.dataset.theme = preference === 'dark' || (preference === 'system' && darkQuery.matches) ? 'dark' : 'light' }
const ThemeContext = createContext<{ preference: ThemePreference; resolved: 'light' | 'dark'; setPreference: (value: ThemePreference) => void }>({ preference: 'light', resolved: 'light', setPreference: () => undefined })
function ThemeProvider({ children }: { children: ReactNode }) {
  const [preference, setPreferenceState] = useState<ThemePreference>(readThemePreference)
  const [systemDark, setSystemDark] = useState(darkQuery.matches)
  useEffect(() => { applyTheme(preference) }, [preference, systemDark])
  useEffect(() => {
    const onSystemChange = (event: MediaQueryListEvent) => setSystemDark(event.matches)
    const onStorage = (event: StorageEvent) => { if (event.key === THEME_KEY) setPreferenceState(readThemePreference()) }
    darkQuery.addEventListener('change', onSystemChange)
    window.addEventListener('storage', onStorage)
    return () => { darkQuery.removeEventListener('change', onSystemChange); window.removeEventListener('storage', onStorage) }
  }, [])
  const setPreference = (value: ThemePreference) => { localStorage.setItem(THEME_KEY, value); setPreferenceState(value) }
  const resolved = preference === 'dark' || (preference === 'system' && systemDark) ? 'dark' : 'light'
  return <ThemeContext.Provider value={{ preference, resolved, setPreference }}>{children}</ThemeContext.Provider>
}

/** Keeps this tab in step with sign-ins/sign-outs made in other tabs instead of mixing two accounts. */
function useCrossTabSession() {
  useEffect(() => {
    let pending: number | undefined
    const sync = () => {
      const current = localStorage.getItem('datanova_token')
      if (tabToken === null || current === tabToken) return
      tabToken = current
      if (!current) { window.location.assign('/login'); return }
      sessionStorage.setItem('datanova_account_switched', readUser()?.email ?? 'another account')
      window.location.assign('/dashboard')
    }
    // Act on the settled state, not on each intermediate write another tab makes while signing in.
    const onStorage = (event: StorageEvent) => { if (event.key !== 'datanova_token' && event.key !== null) return; window.clearTimeout(pending); pending = window.setTimeout(sync, 50) }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [])
}

function readUser(): User | null {
  const value = localStorage.getItem('datanova_user')
  return value ? JSON.parse(value) as User : null
}
// Older builds stored a shared "current dataset" that leaked between accounts; drop it on every sign-in.
function saveSession(token: string, user: User) { sessionStorage.removeItem('datanova_account_switched'); ['datanova_dataset', 'datanova_last_query'].forEach((key) => localStorage.removeItem(key)); tabToken = token; localStorage.setItem('datanova_user', JSON.stringify(user)); localStorage.setItem('datanova_token', token) }
function downloadText(filename: string, content: string) { const url = URL.createObjectURL(new Blob([content], { type: 'text/plain' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url) }

