function Login() {
  const navigate = useNavigate(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [showPassword, setShowPassword] = useState(false); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); setBusy(true); try { const result = await api<{ token: string; user: User }>('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) }); saveSession(result.token, result.user); navigate('/dashboard') } catch (err) { setError((err as Error).message) } finally { setBusy(false) } }
  return <AuthLayout title="Welcome back." copy="Your data has stories waiting to be found. Pick up where you left off."><span className="eyebrow">WELCOME BACK</span><h2>Sign in to your workspace</h2><p className="auth-subtitle">Continue exploring your data with DataNova.</p><form onSubmit={submit} className="auth-form"><label>Email<input required type="email" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@company.com" /></label><label>Password<div className="password-input"><input required minLength={8} type={showPassword ? 'text' : 'password'} value={password} onChange={(event) => setPassword(event.target.value)} placeholder="Enter your password" /><button type="button" onClick={() => setShowPassword(!showPassword)}>{showPassword ? 'Hide' : 'Show'}</button></div></label><div className="form-row"><label className="check-label"><input type="checkbox" /> Remember me</label><Link to="/forgot-password">Forgot password?</Link></div>{error && <div className="form-error">{error}</div>}<button className="primary-button submit-button" disabled={busy}>{busy ? 'Signing in...' : 'Sign in'} <span>↗</span></button><button type="button" className="google-button" onClick={() => setError('Google OAuth is not configured yet. Add GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET to enable it.')}>G <span>Continue with Google</span></button></form><p className="auth-switch">Don't have an account? <Link to="/signup">Create one</Link></p></AuthLayout>
}
