  const submit = async (event: FormEvent) => { event.preventDefault(); if (form.password !== confirm) return setError('Passwords do not match.'); if (!agree) return setError('Accept the terms to create an account.'); setBusy(true); setError(''); try { const result = await api<{ token: string; user: User }>('/api/auth/signup', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); saveSession(result.token, result.user); navigate('/dashboard') } catch (err) { setError((err as Error).message) } finally { setBusy(false) } }
