function ProtectedRoute() { return sessionToken() && readUser() ? <Outlet /> : <Navigate to="/login" replace /> }

type DatasetContextValue = {
  status: DatasetStatus; datasets: DatasetRecord[]; active: DatasetRecord | null; loaded: boolean; listError: string
  selectedFile: File | null; progress: number; uploadError: string; justUploaded: DatasetRecord | null
  insights: Insight[] | null; insightsError: string
  openFilePicker: () => void; retryUpload: () => void; dismissUpload: () => void; selectDataset: (id: number) => void; removeDataset: (id: number) => Promise<void>
}
const DatasetContext = createContext<DatasetContextValue | null>(null)
function useDatasets() { const value = useContext(DatasetContext); if (!value) throw new Error('useDatasets must be used inside DatasetProvider'); return value }
const activeKey = (userId: number) => `datanova_active_dataset:${userId}`

function DatasetProvider({ userId, children }: { userId: number; children: ReactNode }) {
  const [datasets, setDatasets] = useState<DatasetRecord[]>([])
  const [activeId, setActiveId] = useState<number | null>(null)
  const [loaded, setLoaded] = useState(false)
  const [listError, setListError] = useState('')
  const [status, setStatus] = useState<DatasetStatus>('NO_DATA')
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [progress, setProgress] = useState(0)
  const [uploadError, setUploadError] = useState('')
  const [justUploaded, setJustUploaded] = useState<DatasetRecord | null>(null)
  const [insightState, setInsightState] = useState<{ id: number; items: Insight[]; error: string } | null>(null)
  const input = useRef<HTMLInputElement>(null)
  const busy = status === 'UPLOAD_SELECTED' || status === 'UPLOADING' || status === 'PROCESSING'

  const chooseActive = useCallback((id: number | null) => { setActiveId(id); if (id === null) localStorage.removeItem(activeKey(userId)); else localStorage.setItem(activeKey(userId), String(id)) }, [userId])

  useEffect(() => {
    let live = true
    api<{ datasets: DatasetRecord[] }>('/api/datasets').then((result) => {
      if (!live) return
      const stored = Number(localStorage.getItem(activeKey(userId)))
      const initial = result.datasets.find((item) => item.id === stored) ?? result.datasets[0] ?? null
      setDatasets(result.datasets); chooseActive(initial?.id ?? null); setStatus(initial ? 'READY' : 'NO_DATA')
    }).catch((err) => { if (live) setListError((err as Error).message) }).finally(() => { if (live) setLoaded(true) })
    return () => { live = false }
  }, [userId, chooseActive])

  useEffect(() => {
    if (activeId === null) return
    let live = true
    api<{ insights: Insight[] }>(`/api/datasets/${activeId}/insights`).then((result) => { if (live) setInsightState({ id: activeId, items: result.insights, error: '' }) }).catch((err) => { if (live) setInsightState({ id: activeId, items: [], error: (err as Error).message }) })
    return () => { live = false }
  }, [activeId])

  const startUpload = (file: File) => {
    setSelectedFile(file); setUploadError(''); setJustUploaded(null); setProgress(0); setStatus('UPLOAD_SELECTED')
    const extension = file.name.includes('.') ? file.name.slice(file.name.lastIndexOf('.')).toLowerCase() : ''
    const fail = (message: string) => { setUploadError(message); setStatus('ERROR') }
    if (!ACCEPTED_EXTENSIONS.includes(extension)) return fail(`${file.name} is not a CSV or Excel file. Choose a .csv, .xlsx, or .xls file.`)
    if (file.size === 0) return fail(`${file.name} is empty.`)
    if (file.size > MAX_UPLOAD_BYTES) return fail(`${file.name} is larger than 25 MB.`)
    const body = new FormData()
    body.append('file', file)
    // XMLHttpRequest (not fetch) so the UI can tell "bytes still uploading" apart from "server is processing".
    const request = new XMLHttpRequest()
    request.open('POST', `${API}/api/datasets/upload`)
    const token = sessionToken()
    if (token) request.setRequestHeader('Authorization', `Bearer ${token}`)
    request.upload.onprogress = (event) => { if (event.lengthComputable) setProgress(Math.round(event.loaded / event.total * 100)) }
    request.upload.onload = () => { setProgress(100); setStatus('PROCESSING') }
    request.onload = () => {
      let result: Partial<DatasetRecord> & { detail?: string } = {}
      try { result = JSON.parse(request.responseText) } catch { /* non-JSON error body */ }
      if (request.status === 401) { clearSession(); window.location.assign('/login'); return }
      if (request.status < 200 || request.status >= 300 || typeof result.id !== 'number') return fail(result.detail || `Upload failed (HTTP ${request.status}).`)
      const record = result as DatasetRecord
      setDatasets((items) => [record, ...items.filter((item) => item.id !== record.id)])
      chooseActive(record.id); setJustUploaded(record); setSelectedFile(null); setStatus('READY')
    }
    request.onerror = () => fail(`Could not reach the DataNova API at ${API}. Check that the backend is running, then retry.`)
    request.send(body)
    setStatus('UPLOADING')
  }
  const onFileChosen = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    event.target.value = ''
    if (file) startUpload(file)
  }
  const value: DatasetContextValue = {
    status, datasets, loaded, listError, selectedFile, progress, uploadError, justUploaded,
    active: datasets.find((item) => item.id === activeId) ?? null,
    insights: activeId !== null && insightState?.id === activeId ? insightState.items : null,
    insightsError: activeId !== null && insightState?.id === activeId ? insightState.error : '',
    openFilePicker: () => { if (!busy) input.current?.click() },
    retryUpload: () => { if (selectedFile) startUpload(selectedFile) },
    dismissUpload: () => { if (busy) return; setUploadError(''); setSelectedFile(null); setJustUploaded(null); setStatus(activeId !== null ? 'READY' : 'NO_DATA') },
    selectDataset: (id: number) => { chooseActive(id); if (!busy) setStatus('READY') },
    removeDataset: async (id: number) => {
      await api(`/api/datasets/${id}`, { method: 'DELETE' })
      const remaining = datasets.filter((item) => item.id !== id)
      setDatasets(remaining)
      if (justUploaded?.id === id) setJustUploaded(null)
      if (activeId === id) { chooseActive(remaining[0]?.id ?? null); if (!busy) setStatus(remaining[0] ? 'READY' : 'NO_DATA') }
    },
  }
  return <DatasetContext.Provider value={value}><input ref={input} hidden type="file" accept=".csv,.xlsx,.xls,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" onChange={onFileChosen} data-testid="dataset-file-input" />{children}</DatasetContext.Provider>
}

function AccountSwitchNotice() {
  const [email, setEmail] = useState(() => sessionStorage.getItem('datanova_account_switched'))
  if (!email) return null
  const close = () => { sessionStorage.removeItem('datanova_account_switched'); setEmail(null) }
  return <div className="toast-inline upload-status" role="status"><span>You signed in as {email} in another tab, so this tab now shows that account's workspace.</span><button className="row-action-button" onClick={close}>Dismiss</button></div>
}

function UploadStatusBanner() {
  const { status, selectedFile, progress, uploadError, justUploaded, listError, retryUpload, dismissUpload } = useDatasets()
  if (status === 'UPLOADING') return <div className="toast-inline upload-status" role="status"><span className="spinner" />Uploading {selectedFile?.name} · {progress}%<span className="upload-progress"><i style={{ width: `${progress}%` }} /></span></div>
  if (status === 'PROCESSING') return <div className="toast-inline upload-status" role="status"><span className="spinner" />Processing {selectedFile?.name}: reading rows, detecting column types, checking missing values and duplicates…</div>
  if (status === 'ERROR') return <div className="toast-inline upload-status error" role="alert"><span>Upload failed: {uploadError}</span><span className="upload-actions">{selectedFile && <button className="row-action-button" onClick={retryUpload}>Retry</button>}<button className="row-action-button" onClick={dismissUpload}>Dismiss</button></span></div>
  if (justUploaded) return <div className="toast-inline success upload-status" role="status"><span>{justUploaded.name} is ready: {justUploaded.rows.toLocaleString()} rows · {justUploaded.columns} columns · quality {justUploaded.quality_score}/100.</span><span className="upload-actions"><Link to="/dashboard" className="row-action" onClick={dismissUpload}>View dashboard →</Link><button className="row-action-button" onClick={dismissUpload}>Dismiss</button></span></div>
  if (listError) return <div className="toast-inline upload-status error" role="alert"><span>Your datasets could not be loaded: {listError}</span><button className="row-action-button" onClick={() => window.location.reload()}>Retry</button></div>
  return null
}

function AppShell() {
  const [user, setUser] = useState<User | null>(null)
  const [failed, setFailed] = useState(false)
  // The server decides who owns this token; the cached profile in localStorage is never trusted for data scoping.
  useEffect(() => {
    let live = true
    api<{ user: User }>(`/api/auth/me?token=${encodeURIComponent(sessionToken() ?? '')}`).then((result) => { if (!live) return; localStorage.setItem('datanova_user', JSON.stringify(result.user)); setUser(result.user) }).catch(() => { if (!live) return; clearSession(); setFailed(true) })
    return () => { live = false }
  }, [])
  if (failed) return <Navigate to="/login" replace />
  if (!user) return <div className="session-check"><span className="spinner" />Verifying your session…</div>
  return <DatasetProvider key={user.id} userId={user.id}><Shell user={user} /></DatasetProvider>
}
function Shell({ user }: { user: User }) { const navigate = useNavigate(); const location = useLocation(); const { status, active, datasets, insights, openFilePicker, selectDataset } = useDatasets(); const [searchOpen, setSearchOpen] = useState(false); const [notifications, setNotifications] = useState(false); const [mobileOpen, setMobileOpen] = useState(false); const logout = () => { api('/api/auth/logout', { method: 'POST' }).catch(() => undefined).finally(() => { clearSession(); navigate('/login') }) }; const insightCount = insights?.length ?? 0; const activity = active ? [`${active.name} is profiled and ready (${active.rows.toLocaleString()} rows).`, ...(insightCount ? [`${insightCount} insight${insightCount === 1 ? '' : 's'} generated from ${active.name}.`] : [])] : []; const uploadLabel = status === 'UPLOADING' ? 'Uploading…' : status === 'PROCESSING' ? 'Processing…' : '＋ Upload data'; return <div className="app-shell"><aside className={mobileOpen ? 'sidebar mobile-open' : 'sidebar'}><div className="brand-row"><Link to="/dashboard" className="brand"><BrandMark />DataNova <em>AI</em></Link><button className="mobile-close" onClick={() => setMobileOpen(false)}>×</button></div><div className="workspace-label">WORKSPACE <span>⌄</span></div><div className="workspace-card"><div className="avatar">{user.name.slice(0, 2).toUpperCase()}</div><div><strong>Personal workspace</strong><small>{user.email}</small></div><span className="green-dot" /></div><nav>{navItems.map(([label, path, icon]) => <NavLink key={path} to={path} onClick={() => setMobileOpen(false)} className={({ isActive }) => isActive ? 'nav-item active' : 'nav-item'}><span className="nav-icon">{icon}</span>{label}{label === 'Insights' && insightCount > 0 && <span className="new-pill">{insightCount}</span>}</NavLink>)}</nav><div className="sidebar-bottom"><NavLink to="/profile" className="nav-item" onClick={() => setMobileOpen(false)}><span className="nav-icon">◎</span>Profile</NavLink><NavLink to="/settings" className="nav-item" onClick={() => setMobileOpen(false)}><span className="nav-icon">⚙</span>Settings</NavLink><button className="nav-item logout-button" onClick={logout}><span className="nav-icon">↪</span>Log out</button><div className="user-row"><div className="user-avatar">{user.name.slice(0, 2).toUpperCase()}</div><div><strong>{user.name}</strong><small>Workspace admin</small></div></div></div></aside><main className="main-content"><header className="topbar"><button className="mobile-menu" onClick={() => setMobileOpen(true)}>☰</button><div><div className="eyebrow">{location.pathname === '/dashboard' ? 'OVERVIEW' : location.pathname.slice(1).replaceAll('-', ' ').toUpperCase()}</div><h1>{location.pathname === '/dashboard' ? `Good morning, ${user.name.split(' ')[0]}` : pageTitle(location.pathname)}</h1></div><div className="header-actions"><div className={searchOpen ? 'search-box open' : 'search-box'}><button className="icon-button" onClick={() => setSearchOpen(!searchOpen)} title="Search">⌕</button>{searchOpen && <input autoFocus placeholder="Search workspace..." onKeyDown={(event) => event.key === 'Enter' && navigate('/datasets')} />}</div><button className="icon-button notification-button" onClick={() => setNotifications(!notifications)} title="Notifications">♢{activity.length > 0 && <span className="notification-dot" />}</button>{notifications && <div className="notification-popover"><strong>Notifications</strong>{activity.length ? activity.map((item) => <p key={item}>{item}</p>) : <p>No notifications yet.</p>}<Link to={active ? '/insights' : '/datasets'} onClick={() => setNotifications(false)}>{active ? 'View insights →' : 'Upload a dataset →'}</Link></div>}{datasets.length > 1 ? <select className="date-chip" value={active?.id ?? ''} onChange={(event) => selectDataset(Number(event.target.value))} title="Active dataset">{datasets.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select> : <div className="date-chip">▤&nbsp; {active ? active.name : 'No dataset'}</div>}<button type="button" className="primary-button upload-button" onClick={openFilePicker} disabled={status === 'UPLOADING' || status === 'PROCESSING'}>{uploadLabel}</button></div></header><AccountSwitchNotice /><UploadStatusBanner /><Outlet /></main></div> }
function pageTitle(path: string) { const titles: Record<string, string> = { '/datasets': 'Your datasets', '/ask-data': 'Ask Data', '/insights': 'Insights', '/predictions': 'Predictions', '/anomalies': 'Anomalies', '/recommendations': 'Recommendations', '/what-if': 'What-If analysis', '/reports': 'Reports', '/profile': 'Your profile', '/settings': 'Settings' }; return titles[path] || 'DataNova AI' }
function PageIntro({ kicker, title, copy, action }: { kicker: string; title: string; copy: string; action?: ReactNode }) { return <div className="page-intro"><div><span className="eyebrow">{kicker}</span><h2>{title}</h2><p>{copy}</p></div>{action}</div> }
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <article className={`panel ${className}`}>{children}</article> }
function Metric({ label, value, detail, tone }: { label: string; value: string; detail: string; tone: string }) { return <article className={`metric-card ${tone}`}><div className="metric-top"><span>{label}</span><span className="metric-menu">···</span></div><strong>{value}</strong><small>{detail}</small></article> }
function DatasetSummary({ dataset }: { dataset: Dataset }) { return <><div className="dataset-meta"><div className="file-icon">▤</div><div><strong>{dataset.rows.toLocaleString()} rows · {dataset.columns} columns</strong><small>{dataset.lastUpdated}</small></div><span className="status-badge">Ready</span></div><div className="quality-row"><div><span>Data quality score</span><strong>{dataset.quality}<small>/100</small></strong></div><div className="quality-ring"><span>{dataset.quality}%</span></div></div><div className="quality-bar"><span style={{ width: `${dataset.quality}%` }} /></div><div className="dataset-footer"><span>{dataset.missing ?? 0} missing · {dataset.duplicates ?? 0} duplicate rows</span><Link to={`/datasets/${dataset.id}`} className="text-button">Manage →</Link></div></> }
function Activity({ title, copy }: { title: string; copy: string }) { return <div className="activity-item"><span className="activity-icon mint-icon">✦</span><div><strong>{title}</strong><small>{copy}</small></div><span className="check">✓</span></div> }
function Profile() { const user = readUser() ?? { name: '', email: '', id: 0 }; return <><PageIntro kicker="YOUR ACCOUNT" title="Profile" copy="Keep your workspace identity and account details current." /><Card className="profile-card"><div className="profile-avatar">{user.name.slice(0, 2).toUpperCase()}</div><div className="profile-fields"><label>Full name<input defaultValue={user.name} /></label><label>Email<input defaultValue={user.email} disabled /></label><label>Member since<input defaultValue={user.created_at ? new Date(user.created_at).toLocaleDateString() : 'Today'} disabled /></label><button className="primary-button" onClick={() => alert('Profile changes are ready to connect to a profile update endpoint.')}>Save changes <span>↗</span></button></div></Card></> }
function Settings() { const { preference, resolved, setPreference } = useContext(ThemeContext); const [saved, setSaved] = useState(false); const options: [ThemePreference, string, string, string][] = [['light', '☼', 'Light', 'Soft and focused'], ['system', '◐', 'System', `Follow device · now ${resolved}`], ['dark', '◑', 'Dark', 'Easy on the eyes']]; return <><PageIntro kicker="WORKSPACE PREFERENCES" title="Settings" copy="Tune how DataNova feels and when it keeps you informed." />{saved && <div className="toast-inline success">Settings saved for this browser.</div>}<div className="settings-grid"><Card><span className="section-kicker">APPEARANCE</span><h2>Choose your mode</h2><div className="setting-options" role="radiogroup" aria-label="Theme">{options.map(([option, icon, label, hint]) => <button key={option} role="radio" aria-checked={preference === option} className={preference === option ? 'setting-option selected' : 'setting-option'} onClick={() => setPreference(option)}><span>{icon}</span><strong>{label}</strong><small>{hint}</small></button>)}</div><p className="card-copy">Applied instantly and remembered on this browser.</p></Card><Card><span className="section-kicker">NOTIFICATIONS</span><h2>Stay in the loop</h2><div className="toggle-list"><label><span><strong>Email notifications</strong><small>Workspace activity and security</small></span><input type="checkbox" defaultChecked /></label><label><span><strong>Analysis completion</strong><small>When an agent run is ready</small></span><input type="checkbox" defaultChecked /></label><label><span><strong>Report completion</strong><small>When a report is ready to share</small></span><input type="checkbox" /></label></div><button className="primary-button" onClick={() => setSaved(true)}>Save preferences</button></Card></div></> }
function Signal({ tone, title, copy, link }: { tone: string; title: string; copy: string; link: string }) { return <div className="signal-item"><span className={`activity-icon ${tone}`}>✦</span><div><strong>{title}</strong><small>{copy}</small></div><Link to={link}>→</Link></div> }

/** Loads `load()` for `key`; results for a stale key are never shown, so switching datasets cannot leak old numbers. */
function useKeyedLoad<T>(key: string | null, load: () => Promise<T>) {
  const [state, setState] = useState<{ key: string; data: T | null; error: string } | null>(null)
  const loadRef = useRef(load)
  useEffect(() => { loadRef.current = load })
  useEffect(() => {
    if (key === null) return
    let live = true
    loadRef.current().then((data) => { if (live) setState({ key, data, error: '' }) }).catch((err) => { if (live) setState({ key, data: null, error: (err as Error).message }) })
    return () => { live = false }
  }, [key])
  const current = state && state.key === key ? state : null
  return { data: current?.data ?? null, error: current?.error ?? '' }
}

function DynamicChart({ chart }: { chart?: DashboardResponse['chart'] }) {
  if (!chart || !Array.isArray(chart.data) || !chart.data.length) return <div className="empty-chart">No chartable relationship was found for this dataset.</div>
  const max = Math.max(...chart.data.map((item) => item.value), 1)
  return <div className="dynamic-chart"><div className="dynamic-bars">{chart.data.map((item) => <div className="dynamic-bar-item" key={item.label}><div className="dynamic-bar" style={{ height: `${Math.max(4, item.value / max * 100)}%` }} title={`${item.label}: ${item.value}`} /><small>{item.label}</small></div>)}</div><p>{chart.title}{chart.x && chart.y ? ` · ${chart.x} to ${chart.y}` : ''}</p></div>
}

function RealDatasets() { const navigate = useNavigate(); const { datasets, active, loaded, status, openFilePicker, selectDataset, removeDataset } = useDatasets(); const [message, setMessage] = useState(''); const remove = async (id: number, name: string) => { if (!window.confirm(`Delete ${name}? The original and processed copies will be removed.`)) return; try { await removeDataset(id); setMessage(`${name} deleted.`) } catch (err) { setMessage((err as Error).message) } }; const download = async (id: number, name: string) => { const response = await fetch(`${API}/api/datasets/${id}/download?processed=true`, { headers: { Authorization: `Bearer ${sessionToken()}` } }); if (!response.ok) return setMessage('The processed dataset could not be downloaded.'); const blob = await response.blob(); const anchor = document.createElement('a'); anchor.href = URL.createObjectURL(blob); anchor.download = `processed_${name}.csv`; anchor.click() }; const uploadBusy = status === 'UPLOADING' || status === 'PROCESSING'; return <><PageIntro kicker="DATA LIBRARY" title="Your datasets" copy="Every file is profiled, assigned to your account, and analyzed without changing the original upload." action={<button className="primary-button" disabled={uploadBusy} onClick={openFilePicker}>{status === 'UPLOADING' ? 'Uploading…' : status === 'PROCESSING' ? 'Processing…' : '＋ Upload dataset'}</button>} />{message && <div className="toast-inline">{message}</div>}<Card className="dataset-table-card"><div className="table-header"><div><h2>Workspace files</h2><p>{loaded ? `${datasets.length} dataset${datasets.length === 1 ? '' : 's'} owned by this account.` : 'Loading your datasets…'}</p></div><span className="soft-badge">Original + processed</span></div>{loaded && datasets.length === 0 ? <NoDatasetState /> : <div className="dataset-table-scroll"><div className="dataset-row dataset-head"><span>Dataset</span><span>Rows</span><span>Columns</span><span>Quality</span><span>Status</span><span>Actions</span></div>{datasets.map((dataset) => <div className="dataset-row" key={dataset.id}><div className="file-cell"><span className="file-icon">▤</span><div><strong>{dataset.name}</strong><small>{dataset.rows.toLocaleString()} rows · {dataset.missing_values.toLocaleString()} missing</small></div></div><span>{dataset.rows.toLocaleString()}</span><span>{dataset.columns}</span><span><b className="quality-text">{dataset.quality_score}/100</b></span><span className="status-badge">{active?.id === dataset.id ? 'Active' : 'Ready'}</span><span className="row-actions">{active?.id !== dataset.id && <button className="row-action-button" onClick={() => { selectDataset(dataset.id); navigate('/dashboard') }}>Analyze</button>}<Link to={`/datasets/${dataset.id}`} className="row-action">View</Link><button className="row-action-button" onClick={() => download(dataset.id, dataset.name)}>Download</button><button className="row-action-button danger" onClick={() => remove(dataset.id, dataset.name)}>Delete</button></span></div>)}</div>}</Card></> }

function RealDashboard() {
  const { active, loaded, insights } = useDatasets()
  const { data, error } = useKeyedLoad(active ? String(active.id) : null, () => api<DashboardResponse>(`/api/datasets/${active?.id}/dashboard`))
  if (!loaded) return <LoadingState label="Loading your workspace..." />
  if (!active) return <><PageIntro kicker="START WITH REAL DATA" title="Your dashboard is waiting" copy="Upload a CSV or Excel dataset to generate KPIs, charts, quality signals, and insights from your own data." /><NoDatasetState /></>
  if (error) return <ErrorState message={error} />
  if (!data) return <LoadingState label={`Loading analytics for ${active.name}...`} />
  return <><PageIntro kicker="REAL DATA WORKSPACE" title={data.dataset.name} copy={`${data.dataset.rows.toLocaleString()} records · ${data.dataset.columns} columns · analyzed from your uploaded file.`} action={<Link to={`/datasets/${data.dataset.id}`} className="soft-button">Dataset details →</Link>} /><section className="insight-grid">{data.kpis.map((kpi) => <Metric key={kpi.label} label={kpi.label} value={typeof kpi.value === 'number' ? kpi.value.toLocaleString(undefined, { maximumFractionDigits: 2 }) : String(kpi.value)} detail={kpi.detail ?? 'Calculated from current dataset'} tone={kpi.label.toLowerCase().includes('quality') ? 'blue' : 'mint'} />)}</section><section className="content-grid"><Card className="trend-panel"><div className="panel-header"><div><span className="section-kicker">DYNAMIC VISUALIZATION</span><h2>{data.chart?.title || 'Dataset overview'}</h2></div><span className="soft-badge">Actual data</span></div><DynamicChart chart={data.chart} /></Card><Card><span className="section-kicker">DATA QUALITY</span><h2>{data.dataset.quality_score}/100</h2><DatasetSummary dataset={{ id: data.dataset.id, name: data.dataset.name, rows: data.dataset.rows, columns: data.dataset.columns, quality: data.dataset.quality_score, missing: data.dataset.missing_values, duplicates: data.dataset.duplicates, column_names: data.dataset.column_names, lastUpdated: 'Current upload' }} /></Card></section><section className="dashboard-bottom"><Card><div className="panel-header"><div><span className="section-kicker">TOP SIGNALS</span><h2>Insights to explore</h2></div><Link to="/insights" className="text-button">View all →</Link></div>{insights === null ? <p className="card-copy">Generating insights from {data.dataset.name}…</p> : insights.length === 0 ? <p className="card-copy">No insights yet. No measurable pattern was strong enough to report.</p> : <div className="signal-list">{insights.slice(0, 3).map((item, index) => <Signal key={item.title} tone={['mint-icon', 'peach-icon', 'lavender-icon'][index]} title={item.title} copy={item.detail} link={item.link} />)}</div>}</Card><Card><span className="section-kicker">SCHEMA</span><h2>{data.dataset.numeric_columns.length} numerical · {data.dataset.categorical_columns.length} categorical</h2><p className="card-copy">{data.dataset.date_range ? `Date range: ${data.dataset.date_range.start} to ${data.dataset.date_range.end}` : 'No reliable date column detected.'}</p><div className="action-stack"><Link to="/ask-data" className="soft-button">Ask Data <span>→</span></Link><Link to={`/datasets/${data.dataset.id}`} className="soft-button">Inspect columns <span>→</span></Link></div></Card></section></>
}

function RealDatasetDetails() { const { id } = useParams(); const { active, selectDataset } = useDatasets(); const { data, error } = useKeyedLoad(id ?? null, () => api<DatasetRecord>(`/api/datasets/${id}`)); if (error) return <ErrorState message={error} />; if (!data) return <LoadingState label="Loading dataset profile..." />; return <><PageIntro kicker="DATASET PROFILE" title={data.name} copy={`${data.rows.toLocaleString()} rows · ${data.columns} columns · file size ${Math.round(data.file_size / 1024)} KB`} action={<div className="button-row">{active?.id !== data.id && <button className="soft-button" onClick={() => selectDataset(data.id)}>Use this dataset</button>}<Link to="/ask-data" className="primary-button" onClick={() => selectDataset(data.id)}>Ask Data <span>→</span></Link><Link to="/reports" className="soft-button" onClick={() => selectDataset(data.id)}>Generate report</Link></div>} /><section className="detail-grid"><Metric label="Rows" value={data.rows.toLocaleString()} detail="Actual records" tone="mint" /><Metric label="Columns" value={String(data.columns)} detail="Detected fields" tone="blue" /><Metric label="Quality" value={`${data.quality_score}/100`} detail="Calculated score" tone="lavender" /><Metric label="Duplicates" value={String(data.duplicates)} detail="Rows to review" tone="peach" /></section><Card><div className="panel-header"><div><span className="section-kicker">SCHEMA AND QUALITY</span><h2>Column analysis</h2></div><span className="soft-badge">Original preserved</span></div><div className="column-list">{data.columns_detail.map((column) => <div className="column-row" key={column.name}><strong>{column.name}</strong><span>{data.date_columns?.includes(column.name) ? 'date' : column.dtype}</span><small>{column.missing} missing · {column.unique} unique</small></div>)}</div></Card></> }

function RealAskData() { const { active, loaded } = useDatasets(); const [question, setQuestion] = useState(''); const [result, setResult] = useState<{ datasetId: number; question: string; value: QueryResult } | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const ask = async () => { if (!question.trim() || !active) return; const datasetId = active.id; setBusy(true); setError(''); try { setResult({ datasetId, question, value: await postQuery(question, datasetId) }) } catch (err) { setError((err as Error).message) } finally { setBusy(false) } }; if (!loaded) return <LoadingState label="Loading your workspace..." />; if (!active) return <><PageIntro kicker="NATURAL LANGUAGE ANALYTICS" title="Ask Data" copy="Upload a dataset before asking questions. DataNova never substitutes sample data." /><NoDatasetState /></>; const shown = result && result.datasetId === active.id ? result : null; return <><PageIntro kicker="NATURAL LANGUAGE ANALYTICS" title="Ask Data" copy={`Ask a question about ${active.name}. Answers and charts below are calculated from this file.`} /><div className="ask-layout"><Card className="conversation"><div className="conversation-top"><span className="agent-status"><i /> Agents ready</span><span className="soft-badge">{active.name}</span></div>{!shown && <div className="chat-empty"><span className="chat-spark">✦</span><h3>What would you like to understand?</h3><p>Try a total, comparison, trend, anomaly, correlation, or scenario.</p></div>}{shown && <div className="answer-card"><div className="answer-heading"><span>RESULT FROM ACTUAL DATA</span><small>{shown.question}</small></div><h3>{shown.value.answer}</h3>{shown.value.chart && <DynamicChart chart={shown.value.chart} />}<div className="agents-used"><span>Analysis stages</span>{(shown.value.agents || []).map((agent) => <small key={agent}>✓ {agent}</small>)}</div></div>}<div className="query-box large-query"><textarea value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); ask() } }} placeholder="Ask anything about your data..." rows={3} /><div className="query-actions"><span className="voice-button">Type a question to keep the result reviewable</span><button className="ask-button" disabled={busy} onClick={ask}>{busy ? 'Analyzing...' : 'Send'} <span>↗</span></button></div></div>{error && <div className="form-error">{error}</div>}</Card><aside className="ask-sidebar"><Card><span className="section-kicker">TRY A PROMPT</span><h2>Questions for this schema</h2><div className="prompt-list">{['Show me the overall performance.', 'Which group has the highest total?', 'Show monthly trends.', 'Find anomalies in the dataset.', 'Give me insights from this dataset.', 'What should we focus on?'].map((prompt) => <button key={prompt} onClick={() => setQuestion(prompt)}>{prompt}<span>↗</span></button>)}</div></Card><Card><span className="section-kicker">AGENT ACTIVITY</span><h2>High-level process</h2><div className="activity-list compact"><Activity title="Profile dataset" copy="Detect columns and data types" /><Activity title="Calculate answer" copy="Run a controlled operation" /><Activity title="Explain result" copy="Show evidence and chart" /></div></Card></aside></div></> }

function RealQueryPage({ intent, title, copy, question }: { intent: string; title: string; copy: string; question: string }) { const { active, loaded } = useDatasets(); const { data: result, error } = useKeyedLoad(active ? `${active.id}:${question}` : null, () => postQuery(question, active!.id)); if (!loaded) return <LoadingState label="Loading your workspace..." />; if (!active) return <><PageIntro kicker={intent} title={title} copy={copy} /><NoDatasetState /></>; if (error) return <ErrorState message={error} />; if (!result) return <LoadingState label={`Running ${title.toLowerCase()} on ${active.name}...`} />; return <><PageIntro kicker={intent} title={title} copy={copy} /><Card className="analysis-result"><div className="answer-heading"><span>RESULT FROM ACTUAL DATA</span><small>{active.name}</small></div><h2>{result.answer}</h2><div className="agents-used"><span>Analysis stages</span>{(result.agents || []).map((agent) => <small key={agent}>✓ {agent}</small>)}</div>{result.chart && <DynamicChart chart={result.chart} />}{result.supporting_data && <pre className="supporting-json">{JSON.stringify(result.supporting_data, null, 2)}</pre>}</Card></> }
function InsightCard({ insight }: { insight: Insight }) { return <Card className="insight-page-card"><div className="card-topline"><span className={`soft-badge ${insight.tone}`}>{insight.category}</span><span className="confidence">Calculated from data</span></div><h2>{insight.title}</h2><p>{insight.detail}</p><div className="support-metric"><span>Supporting metric</span><strong>{insight.metric}</strong></div><Link to={insight.link} className="text-button">View analysis →</Link></Card> }
function RealInsights() { const { active, loaded, insights, insightsError } = useDatasets(); const intro = <PageIntro kicker="EVIDENCE, NOT NOISE" title="Insights" copy={active ? `Findings calculated from ${active.name}.` : 'Findings are calculated only from datasets you upload.'} />; if (!loaded) return <LoadingState label="Loading your workspace..." />; if (!active) return <>{intro}<Card className="empty-state"><span className="chat-spark">◒</span><h2>No insights yet</h2><p>Upload and analyze a dataset to generate insights.</p><UploadDataButton /></Card></>; if (insightsError) return <>{intro}<ErrorState message={insightsError} /></>; if (insights === null) return <>{intro}<LoadingState label={`Generating insights from ${active.name}...`} /></>; if (insights.length === 0) return <>{intro}<Card className="empty-state"><span className="chat-spark">◒</span><h2>No insights yet</h2><p>No measurable pattern in {active.name} was strong enough to report. Try Ask Data for specific questions.</p></Card></>; return <>{intro}<div className="insight-page-grid">{insights.map((insight) => <InsightCard key={insight.title} insight={insight} />)}</div></> }
type Forecast = { available: boolean; reason?: string; column?: string; next_period?: string; prediction?: number; mae?: number; historical?: { period: string; value: number }[] }
function RealPredictions() { const { active, loaded } = useDatasets(); const { data: forecast, error } = useKeyedLoad(active ? String(active.id) : null, () => api<Forecast>(`/api/datasets/${active!.id}/forecast`)); if (!loaded) return <LoadingState label="Loading your workspace..." />; if (!active) return <><PageIntro kicker="ESTIMATED OUTCOMES" title="Predictions" copy="Upload a dataset with dates and a numerical measure before forecasting." /><NoDatasetState /></>; if (error) return <ErrorState message={error} />; if (!forecast) return <LoadingState label="Checking whether this dataset supports forecasting..." />; if (!forecast.available) return <><PageIntro kicker="ESTIMATED OUTCOMES" title="Predictions" copy="Prediction is not available for this dataset." /><Card className="empty-state"><h2>Prediction cannot be reliably generated</h2><p>{forecast.reason}</p><Link to={`/datasets/${active.id}`} className="soft-button">Review dataset profile →</Link></Card></>; return <><PageIntro kicker="ESTIMATED OUTCOMES" title="Predictions" copy={`Directional forecast for ${active.name}. This is an estimate, not a guaranteed outcome.`} /><div className="detail-grid"><Metric label={`Next ${forecast.column}`} value={Number(forecast.prediction).toLocaleString()} detail={forecast.next_period || 'Next period'} tone="mint" /><Metric label="MAE" value={Number(forecast.mae).toLocaleString()} detail="Historical fit error" tone="lavender" /><Metric label="History" value={String(forecast.historical?.length || 0)} detail="Monthly points used" tone="blue" /></div><Card><div className="panel-header"><div><span className="section-kicker">HISTORICAL + ESTIMATED</span><h2>{forecast.column} trend</h2></div><span className="soft-badge">Estimated</span></div><DynamicChart chart={{ type: 'line', title: `Monthly ${forecast.column}`, data: forecast.historical?.map((item) => ({ label: item.period, value: item.value })) }} /></Card></> }
function RealAnomalies() { return <RealQueryPage intent="REVIEWABLE SIGNALS" title="Anomalies" copy="Potential anomalies are statistical signals for review, never confirmed errors." question="Find unusual values and anomalies" /> }
function RealRecommendations() { return <RealQueryPage intent="DECISION SUPPORT" title="Recommendations" copy="Recommendations are generated from the current dataset's calculated signals." question="What should we focus on based on this dataset?" /> }
function RealWhatIf() { const { active, loaded } = useDatasets(); const [change, setChange] = useState(10); const [result, setResult] = useState<{ datasetId: number; value: QueryResult } | null>(null); const [error, setError] = useState(''); const run = async () => { if (!active) return; setError(''); try { setResult({ datasetId: active.id, value: await postQuery(`What if the main measure changes by ${change}%?`, active.id) }) } catch (err) { setError((err as Error).message) } }; if (!loaded) return <LoadingState label="Loading your workspace..." />; if (!active) return <><PageIntro kicker="SCENARIO LAB" title="What-If analysis" copy="Upload a dataset first so the simulation can use an observed numerical measure." /><NoDatasetState /></>; const shown = result?.datasetId === active.id ? result.value : null; return <><PageIntro kicker="SCENARIO LAB" title="What-If analysis" copy="This simulation applies a controlled change to the main numerical measure detected in your dataset." /><div className="what-if-layout"><Card><span className="section-kicker">SIMULATION INPUT</span><h2>{change > 0 ? '+' : ''}{change}% change</h2><input className="range-input" type="range" min="-50" max="100" value={change} onChange={(event) => setChange(Number(event.target.value))} /><button className="primary-button full-button" onClick={run}>Run simulation <span>↗</span></button></Card><Card className="scenario-result">{error ? <div className="form-error">{error}</div> : shown ? <><div className="simulated-label">SIMULATION — NOT A GUARANTEED FORECAST</div><h2>{shown.answer}</h2><div className="agents-used">{(shown.agents || []).map((agent) => <small key={agent}>✓ {agent}</small>)}</div></> : <div className="empty-chart">Choose a scenario and run it against {active.name}.</div>}</Card></div></> }
function RealReports() { const { active, loaded, insights } = useDatasets(); const [report, setReport] = useState<{ datasetId: number; summary: QueryResult; recommendation: QueryResult; generatedAt: string } | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const generate = async () => { if (!active) return; setBusy(true); setError(''); try { const [summary, recommendation] = await Promise.all([postQuery('Give me an executive summary of this dataset', active.id), postQuery('What should we focus on based on this dataset?', active.id)]); setReport({ datasetId: active.id, summary, recommendation, generatedAt: new Date().toLocaleString() }) } catch (err) { setError((err as Error).message) } finally { setBusy(false) } }; if (!loaded) return <LoadingState label="Loading your workspace..." />; if (!active) return <><PageIntro kicker="STORYTELLING" title="Reports" copy="Upload and analyze a dataset before generating a report." /><NoDatasetState /></>; const shown = report?.datasetId === active.id ? report : null; const findings = (insights || []).slice(0, 4); const download = () => { if (!shown) return; downloadText(`${active.name}-report.txt`, ['DATANOVA AI REPORT', `Dataset: ${active.name}`, `Generated: ${shown.generatedAt}`, `${active.rows.toLocaleString()} rows · ${active.columns} columns · quality ${active.quality_score}/100`, '', 'EXECUTIVE SUMMARY', shown.summary.answer, '', 'KEY FINDINGS', ...(findings.length ? findings.map((item) => `- ${item.title}: ${item.detail}`) : ['- No measurable pattern was strong enough to report.']), '', 'RECOMMENDATION', shown.recommendation.answer].join('\n')) }; return <><PageIntro kicker="STORYTELLING" title="Reports" copy="Generate a narrative from the current dataset's computed results." action={<button className="primary-button" onClick={generate} disabled={busy}>{busy ? 'Generating...' : '＋ Generate report'}</button>} />{error && <div className="form-error">{error}</div>}{shown ? <Card className="report-card"><div className="report-cover"><span className="eyebrow peach">ACTUAL DATA REPORT</span><h2>{active.name}<br /><i>in focus.</i></h2><p>Generated {shown.generatedAt}</p></div><div className="report-story"><span className="section-kicker">EXECUTIVE SUMMARY</span><h2>{shown.summary.answer}</h2><div className="story-sections"><div><strong>KEY FINDINGS</strong>{findings.length ? findings.map((item) => <span key={item.title}>{item.title}.</span>) : <span>No measurable pattern was strong enough to report.</span>}</div><div><strong>RECOMMENDATIONS</strong><span>{shown.recommendation.answer}</span></div></div><div className="button-row"><button className="soft-button" onClick={download}>Download report</button></div></div></Card> : <Card className="empty-state"><span className="chat-spark">▤</span><h2>No report generated yet</h2><p>Generate a report to summarize {active.name} from its calculated results.</p></Card>}</> }
function LoadingState({ label }: { label: string }) { return <Card className="empty-state"><span className="spinner" /><h2>{label}</h2><p>No placeholder numbers are shown while DataNova reads your data.</p></Card> }
function ErrorState({ message }: { message: string }) { return <Card className="empty-state error-state"><span>!</span><h2>Analysis unavailable</h2><p>{message}</p><button className="soft-button" onClick={() => window.location.reload()}>Retry</button></Card> }
function UploadDataButton() { const { status, openFilePicker } = useDatasets(); const busy = status === 'UPLOADING' || status === 'PROCESSING'; return <button className="primary-button" onClick={openFilePicker} disabled={busy}>{status === 'UPLOADING' ? 'Uploading…' : status === 'PROCESSING' ? 'Processing…' : 'Upload Data'} <span>↗</span></button> }
function NoDatasetState() { return <Card className="empty-state"><span className="chat-spark">▦</span><h2>No dataset uploaded yet</h2><p>Upload a CSV or Excel file to start analyzing your data.</p><UploadDataButton /></Card> }

export default App
